{"path":"assets/css/styles.css","content":"/* Minimal, poetic zen design */
:root{
  --bg:#fbfbfb;
  --card:#ffffff;
  --muted:#6b7280;
  --accent-start:#89f7fe;
  --accent-end:#66a6ff;
  --accent-deep:#556270;
  --text:#0f172a;
  --radius:12px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:var(--text);background:linear-gradient(180deg,var(--bg) 0%,#ffffff 100%);margin:0}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));border-bottom:1px solid rgba(15,23,42,0.04)}
.site-header .wrap{display:flex;gap:16px;align-items:center}
.brand{font-weight:700;color:var(--accent-deep);text-decoration:none;font-size:1.05rem}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.primary{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));color:#022;box-shadow:0 6px 18px rgba(100,120,255,0.08);}
.nav-toggle{display:none;background:none;border:0;font-size:1.125rem}

.hero{position:relative;padding:56px 0;overflow:hidden}
.hero .pattern{position:absolute;left:-10%;top:-10%;width:140%;height:140%;opacity:0.18;filter:blur(0.5px)}
.hero-grid{display:grid;grid-template-columns:1fr 240px;gap:28px;align-items:center}
.title{font-size:2rem;margin:0 0 6px 0;color:var(--accent-deep)}
.subtitle{margin:0 0 12px 0;color:var(--muted)}
.lead{margin:0 0 18px 0;color:#263238}
.hero-ctas{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--text)}
.btn-primary{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));color:#022;border:0}
.meta-card{background:var(--card);padding:10px;border-radius:10px;margin-bottom:12px;box-shadow:0 6px 20px rgba(9,30,66,0.03)}
.meta-card a{color:var(--accent-deep);text-decoration:none}

.card-section{padding:36px 0}
.card-section .muted{color:var(--muted);margin-bottom:12px}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.card{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 8px 30px rgba(15,23,42,0.04)}
.pillar{background:linear-gradient(180deg,#fff,rgba(255,255,255,0.9));padding:16px;border-radius:10px;text-align:left}

.case-notes .notes{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:14px}
.note{background:var(--card);padding:14px;border-radius:10px}

.faq .accordion{display:block}
.qa{margin-bottom:10px;background:var(--card);border-radius:10px;overflow:hidden}
.q{width:100%;text-align:left;padding:14px;border:0;background:linear-gradient(90deg,rgba(100,120,255,0.06),transparent);cursor:pointer}
.q[aria-expanded="true"]{background:linear-gradient(90deg,var(--accent-start),var(--accent-end));color:#022}
.a{padding:12px 14px;border-top:1px solid rgba(15,23,42,0.03);display:none}

.cta{padding:48px 0;text-align:center;background:linear-gradient(180deg,rgba(102,166,255,0.06),transparent)}
.cta .cta-actions{display:flex;gap:12px;justify-content:center;margin:18px 0}
.credit{color:var(--muted);font-size:0.95rem}

.site-footer{border-top:1px solid rgba(15,23,42,0.04);padding:22px 0;margin-top:24px}
.site-footer p{margin:0;color:var(--muted)}
.foot-nav{margin-top:8px}
.foot-nav a{color:var(--muted);text-decoration:none;margin-right:12px}

/* Responsive */
@media(max-width:900px){
  .grid-3{grid-template-columns:1fr}
  .grid-4{grid-template-columns:1fr 1fr}
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}
@media(max-width:520px){
  .grid-4{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // nav toggle
  var btn=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.nav');
  if(btn && nav){
    btn.addEventListener('click',function(){
      var expanded=this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded',!expanded);
      nav.style.display = expanded ? 'none' : 'flex';
    });
    window.addEventListener('resize',function(){ if(window.innerWidth>900) nav.style.display='flex'; });
  }

  // accordion
  document.querySelectorAll('.qa').forEach(function(item){
    var q=item.querySelector('.q');
    var a=item.querySelector('.a');
    q.addEventListener('click',function(){
      var open=this.getAttribute('aria-expanded')==='true';
      document.querySelectorAll('.qa .q').forEach(function(b){ b.setAttribute('aria-expanded','false'); b.nextElementSibling.style.display='none'; });
      if(!open){
        this.setAttribute('aria-expanded','true');
        a.style.display='block';
      }
    });
  });

  // smooth scroll for in-page anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(link){
    link.addEventListener('click',function(e){
      e.preventDefault(); var id=this.getAttribute('href').slice(1); var el=document.getElementById(id); if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

});"} 
